mapper.select:
SELECT
FROM `user` WHERE deleted = 0 AND id IN
#{id}

mapper.update:
UPDATE `user`
SET password = #{password}
WHERE id = #{id} AND deleted = 0

UPDATE `user`
SET points = points + #{delta}
WHERE id = #{id} AND deleted = 0

mapper.select:
SELECT
FROM `user` WHERE role = 'MEMBER' AND deleted = 0
AND (real_name LIKE CONCAT('%', #{keyword}, '%') OR phone LIKE CONCAT('%', #{keyword}, '%'))
AND status = #{status}
AND member_level = #{memberLevel}
ORDER BY create_time DESC, id DESC

mapper.update:
UPDATE `user`
SET status = #{status}
WHERE id = #{id} AND deleted = 0

UPDATE `user`
SET member_level = #{memberLevel}
WHERE id = #{id} AND deleted = 0

UPDATE `user`
SET role = #{role}
WHERE id = #{id} AND deleted = 0

UPDATE `user`
SET points = points - #{amount}
WHERE id = #{id} AND points >= #{amount} AND deleted = 0
